B.bqa=new A.dU("Scan it and enter your PIN, and money goes to {payee}. A QR never brings money in.","\u0938\u094d\u0915\u0948\u0928 \u0915\u0930\u0915\u0947 PIN \u0921\u093e\u0932\u0924\u0947 \u0939\u0940 \u092a\u0948\u0938\u0947 {payee} \u0915\u094b \u091a\u0932\u0947 \u091c\u093e\u0924\u0947 \u0939\u0948\u0902\u0964 QR \u0938\u0947 \u0915\u092d\u0940 \u092a\u0948\u0938\u0947 \u0906\u0924\u0947 \u0928\u0939\u0940\u0902\u0964","\u0938\u094d\u0915\u0945\u0928 \u0915\u0930\u0942\u0928 PIN \u091f\u093e\u0915\u0924\u093e\u091a \u092a\u0948\u0938\u0947 {payee} \u0932\u093e \u091c\u093e\u0924\u093e\u0924. QR \u0928\u0947 \u0915\u0927\u0940\u091a \u092a\u0948\u0938\u0947 \u092f\u0947\u0924 \u0928\u093e\u0939\u0940\u0924.")
B.bqb=new A.dU("Nox only knows the scams on its list. Check on the official number or app before you pay.","Nox \u0938\u093f\u0930\u094d\u092b\u093c \u0905\u092a\u0928\u0940 \u0932\u093f\u0938\u094d\u091f \u0935\u093e\u0932\u0947 \u0938\u094d\u0915\u0948\u092e \u092a\u0939\u091a\u093e\u0928\u0924\u093e \u0939\u0948\u0964 \u092a\u0948\u0938\u0947 \u0926\u0947\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0911\u092b\u093c\u093f\u0936\u093f\u092f\u0932 \u0928\u0902\u092c\u0930 \u092f\u093e \u0910\u092a \u092a\u0930 \u091c\u093e\u0902\u091a \u0932\u0947\u0902\u0964","Nox \u0932\u093e \u092b\u0915\u094d\u0924 \u0924\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092f\u093e\u0926\u0940\u0924\u0932\u0947 \u0938\u094d\u0915\u0945\u092e \u0913\u0933\u0916\u0924\u093e \u092f\u0947\u0924\u093e\u0924. \u092a\u0948\u0938\u0947 \u0926\u0947\u0923\u094d\u092f\u093e\u0906\u0927\u0940 \u0905\u0927\u093f\u0915\u0943\u0924 \u0928\u0902\u092c\u0930 \u0915\u093f\u0902\u0935\u093e \u0972\u092a\u0935\u0930 \u0916\u093e\u0924\u094d\u0930\u0940 \u0915\u0930\u093e.")
B.bqc=new A.dU("Red flags Nox found","Nox \u0915\u094b \u092e\u093f\u0932\u0947 \u0916\u0924\u0930\u0947 \u0915\u0947 \u0928\u093f\u0936\u093e\u0928","Nox \u0932\u093e \u0938\u093e\u092a\u0921\u0932\u0947\u0932\u0940 \u0927\u094b\u0915\u094d\u092f\u093e\u091a\u0940 \u091a\u093f\u0928\u094d\u0939\u0902")
B.bqd=new A.dU("This PDF couldn\u2019t be opened. Take a screenshot of it and check that.","\u092f\u0947 PDF \u0916\u0941\u0932 \u0928\u0939\u0940\u0902 \u092a\u093e\u0908\u0964 \u0907\u0938\u0915\u093e \u0938\u094d\u0915\u094d\u0930\u0940\u0928\u0936\u0949\u091f \u0932\u0947\u0915\u0930 \u091c\u093e\u0902\u091a\u0947\u0902\u0964","\u0939\u0940 PDF \u0909\u0918\u0921\u0932\u0940 \u0928\u093e\u0939\u0940. \u0924\u093f\u091a\u093e \u0938\u094d\u0915\u094d\u0930\u0940\u0928\u0936\u0949\u091f \u0918\u0947\u090a\u0928 \u0924\u092a\u093e\u0938\u093e.")
B.bqe=new A.dU("Scan it and enter your PIN, and {amount} goes to {payee}. A QR never brings money in.","\u0938\u094d\u0915\u0948\u0928 \u0915\u0930\u0915\u0947 PIN \u0921\u093e\u0932\u0924\u0947 \u0939\u0940 {amount} {payee} \u0915\u094b \u091a\u0932\u0947 \u091c\u093e\u090f\u0902\u0917\u0947\u0964 QR \u0938\u0947 \u0915\u092d\u0940 \u092a\u0948\u0938\u0947 \u0906\u0924\u0947 \u0928\u0939\u0940\u0902\u0964","\u0938\u094d\u0915\u0945\u0928 \u0915\u0930\u0942\u0928 PIN \u091f\u093e\u0915\u0924\u093e\u091a {amount} {payee} \u0932\u093e \u091c\u093e\u0924\u0940\u0932. QR \u0928\u0947 \u0915\u0927\u0940\u091a \u092a\u0948\u0938\u0947 \u092f\u0947\u0924 \u0928\u093e\u0939\u0940\u0924.")
B.CS=new A.dU("Nox Check","Nox Check","Nox Check")
B.bqf=new A.dU("Nox couldn\u2019t read any words here. Paste the message text instead.","Nox \u0915\u094b \u092f\u0939\u093e\u0902 \u0915\u094b\u0908 \u0936\u092c\u094d\u0926 \u0928\u0939\u0940\u0902 \u092e\u093f\u0932\u0947\u0964 \u092e\u0948\u0938\u0947\u091c \u0915\u093e \u091f\u0947\u0915\u094d\u0938\u094d\u091f \u092a\u0947\u0938\u094d\u091f \u0915\u0930\u0947\u0902\u0964","Nox \u0932\u093e \u0907\u0925\u0947 \u0915\u094b\u0923\u0924\u0947\u0939\u0940 \u0936\u092c\u094d\u0926 \u0938\u093e\u092a\u0921\u0932\u0947 \u0928\u093e\u0939\u0940\u0924. \u092e\u0947\u0938\u0947\u091c\u091a\u093e \u092e\u091c\u0915\u0942\u0930 \u092a\u0947\u0938\u094d\u091f \u0915\u0930\u093e.")
B.bqg=new A.dU("NO SUS is independent. Not affiliated with the Government of India.","NO SUS \u090f\u0915 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0910\u092a \u0939\u0948\u0964 \u092d\u093e\u0930\u0924 \u0938\u0930\u0915\u093e\u0930 \u0938\u0947 \u0938\u0902\u092c\u0926\u094d\u0927 \u0928\u0939\u0940\u0902\u0964","NO SUS \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0972\u092a \u0906\u0939\u0947. \u092d\u093e\u0930\u0924 \u0938\u0930\u0915\u093e\u0930\u0936\u0940 \u0938\u0902\u0932\u0917\u094d\u0928 \u0928\u093e\u0939\u0940.")
B.XK=new A.dU("Make a SUS card","SUS \u0915\u093e\u0930\u094d\u0921 \u092c\u0928\u093e\u090f\u0902","SUS \u0915\u093e\u0930\u094d\u0921 \u092c\u0928\u0935\u093e")
B.bqh=new A.dU("Share the card","\u0915\u093e\u0930\u094d\u0921 \u0936\u0947\u092f\u0930 \u0915\u0930\u0947\u0902","\u0915\u093e\u0930\u094d\u0921 \u0936\u0947\u0905\u0930 \u0915\u0930\u093e")
